 if(step.kind==='communication_send')return result('waiting','Waiting for provider details','Gmail or RingCentral connection, recipients and content are supplied when a run prepares its reviewed draft. This definition stores no provider mapping and does not send automatically.');
 if(step.kind==='eligibility_query')return result('waiting','Waiting for run coverage details','Open patient billing to select coverage and prepare the coverage request. A current returned response is required; this definition does not confirm payer or connection readiness.');
 if(step.kind==='payment_request')return result('waiting','Waiting for run payment details','Choose the patient account and amount in billing. Payment proof currently uses the test processor; preparing a request does not mean a payment was collected.');
 if(step.kind==='patient_form')return (step.form_fields||[]).length?result('configured','Configured · patient intake','The form fields are saved with this definition. Issue them from an appointment-linked run, then review the submitted answers and any chart handoff.'):result('waiting','Waiting for form fields','Add patient intake fields in Forms before issuing this node’s packet.');
