function studioValidation(){const steps=studioDraft.definition.steps,columns=studioColumns(),keys=new Set(steps.map(s=>s.key)),columnKeys=new Set(columns.map(c=>c.key)),issues=[];if(!studioDraft.name.trim())issues.push('Give this workflow a name.');if(!columns.length)issues.push('Add at least one column.');if(columns.every(c=>c.hidden))issues.push('Keep at least one column visible.');if(columnKeys.size!==columns.length)issues.push('Column IDs must be unique.');if(!steps.length)issues.push('Add at least one step.');if(keys.size!==steps.length)issues.push('Node IDs must be unique.');for(const s of steps){issues.push(...studioAiValidation(s),...studioNativeValidation(s),...studioFormMappingValidation(s));if(!columnKeys.has(studioPhase(s)))issues.push(`${s.title} is assigned to a missing column.`);for(const d of s.depends_on||[])if(!keys.has(d))issues.push(`${s.title} depends on a missing step.`);if(s.condition&&(!s.condition.field.startsWith('/')||s.condition.field.length>200||!['equals','not_equals','present','absent'].includes(s.condition.operator)))issues.push(`${s.title} has an invalid run condition.`)}const visiting=new Set(),visited=new Set(),byKey=new Map(steps.map(s=>[s.key,s]));function visit(key){if(visited.has(key))return;if(visiting.has(key)){issues.push('Workflow connections must not contain a cycle.');return}visiting.add(key);for(const dependency of byKey.get(key)?.depends_on||[])if(byKey.has(dependency))visit(dependency);visiting.delete(key);visited.add(key)}for(const key of keys)visit(key);return [...new Set(issues)]}
