function studioForms(){const forms=studioDraft.definition.steps.filter(s=>['patient_form','clinical_template'].includes(s.kind));if(!forms.length)return `<main class="studio-section"><section class="studio-onboarding"><h3>No forms in this workflow yet</h3><p>Add a patient form, then define its fields here.</p><button class="primary" data-studio-add-form>Add a patient form</button></section></main>`;if(!forms.includes(studioStep()))studioDraft._selectedStep=forms[0].key;const s=studioStep();return `<main class="studio-section"><div class="studio-forms-layout"><aside><p class="eyebrow">WORKFLOW FORMS</p>${forms.map(x=>`<button class="studio-form-row ${x.key===s.key?'selected':''}" data-studio-node="${esc(x.key)}"><b>${esc(x.title)}</b><small>${x.form_fields.length} field${x.form_fields.length===1?'':'s'}</small></button>`).join('')}<button data-studio-add-form>+ Add form</button></aside><section class="studio-form-editor"><p class="eyebrow">FORM BUILDER</p><h3>${esc(s.title)}</h3>${s.kind==='patient_form'?`<p class="muted">Required answers are checked when the patient submits the issued intake packet. Chart destinations require a separate staff review and apply action.</p>${studioFields(s)}`:`<p class="muted">Clinical documentation uses the native record form selected below. Saved custom fields remain in this definition but are not added to that clinical record.</p>${studioNativeInspector(s)}${s.form_fields.length?`<details><summary>Saved field definitions (${s.form_fields.length})</summary><ul>${s.form_fields.map(field=>`<li>${esc(field.label)} · ${esc(human(field.field_type))}</li>`).join('')}</ul></details>`:''}`} </section></div></main>`}
