document.addEventListener('change',e=>{if(e.target.hasAttribute('data-studio-identity-reason')){if(me?.role!=='owner'||!studioWorkspace)return;studioWorkspace.content.require_identity_correction_reason=e.target.checked;studioWorkspaceDirty=true;studioRender();return}if(e.target.hasAttribute('data-studio-map-select')){const key=e.target.value;if(studioWorkspace?.content.module_order.includes(key)){studioWorkspaceMapSelection={module:key,kind:'navigation',key};studioRender();}return}if(e.target.dataset.studioModuleGroup){studioWorkspaceSetGroup(e.target.dataset.studioModuleGroup,e.target.value);return}if(e.target.dataset.studioModuleLabel){studioRender();return}if(e.target.hasAttribute('data-studio-select'))run(async()=>{studioSelected=e.target.value;await studioLoad(studioSelected)})});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.studioModuleLabel){studioWorkspaceSetLabel(t.dataset.studioModuleLabel,t.value);return}if(t.hasAttribute('data-studio-workspace-reason')){studioWorkspaceReason=t.value;return}if(t.dataset.studioMapVisible){studioWorkspaceToggle(t.dataset.studioMapVisible);return}if(t.dataset.studioChartToggle){studioWorkspaceChartToggle(t.dataset.studioChartToggle);return}if(!studioDraft)return;if(t.dataset.studioMeta){studioDraft[t.dataset.studioMeta]=t.value;studioInputChanged();return}if(t.dataset.studioColumnTitle){const column=studioColumns().find(item=>item.key===t.dataset.studioColumnTitle);if(column)column.title=t.value;studioInputChanged();return}const s=studioStep();if(!s)return;if(t.hasAttribute('data-studio-native-resource')){if(t.value)s.native={resource:t.value};else delete s.native;studioInputChanged();studioRefreshInspector();return}if(t.hasAttribute('data-studio-condition-enable')){s.condition=t.checked?{field:'/field',operator:'equals',value:''}:null;studioChange();return}if(t.hasAttribute('data-studio-condition-value-type')){s.condition.value=studioCastConditionValue(s.condition.value,t.value);studioChange();return}if(t.dataset.studioConditionProperty){const property=t.dataset.studioConditionProperty;if(property==='field')s.condition.field=t.value;else if(property==='operator')s.condition.operator=t.value;else s.condition.value=studioCastConditionValue(t.value,t.dataset.valueType||'string');studioInputChanged();if(property==='operator')studioRender();return}if(t.dataset.studioAiProperty){s.ai={...(s.ai||{}),[t.dataset.studioAiProperty]:t.value};s.manual_approval=true;studioInputChanged();return}if(t.dataset.studioProperty){const p=t.dataset.studioProperty;if(p==='due_hours')s.due_after_minutes=t.value?Number(t.value)*60:null;else if(['required','manual_approval'].includes(p))s[p]=t.checked;else s[p]=t.value||null;if(p==='kind'&&s.native&&typeof journeyNativeAllowed==='function'&&!journeyNativeAllowed(s.kind).includes(s.native.resource))delete s.native;if(p==='kind'&&(studioAiKinds.has(s.kind)||s.kind==='human_approval'))s.manual_approval=true;studioInputChanged();if(p==='kind')studioRender();return}if(t.dataset.studioDependency){const set=new Set(s.depends_on);t.checked?set.add(t.dataset.studioDependency):set.delete(t.dataset.studioDependency);s.depends_on=[...set];studioInputChanged();if(studioVisualEditor)void studioVisualEditor.syncConnections(studioClone(studioDraft.definition.steps));return}const row=t.closest('[data-form-field]');if(row&&t.dataset.fieldProperty){const f=s.form_fields[Number(row.dataset.formField)],p=t.dataset.fieldProperty;if(p==='required')f.required=t.checked;else if(p==='options')f.options=t.value.split(',').map(x=>x.trim()).filter(Boolean);else if(p==='chart_target'){if(t.value&&(!Object.hasOwn(studioChartTargets,t.value)||!studioMappedFieldTypes.has(f.field_type)||s.form_fields.some(other=>other!==f&&other.chart_target===t.value))){notice('Choose an unused chart destination for a text or choice field.',true);studioRender();return}if(t.value)f.chart_target=t.value;else delete f.chart_target;}else{f[p]=t.value;if(p==='label')f.key=studioKey(t.value);if(p==='field_type'&&!studioMappedFieldTypes.has(f.field_type))delete f.chart_target;}studioInputChanged();if(['field_type','chart_target'].includes(p))studioRender()}});
document.addEventListener('dragstart',e=>{const n=e.target.closest('[data-studio-node]');if(!n)return;studioDragKey=n.dataset.studioNode;e.dataTransfer.setData('text/plain',studioDragKey)});document.addEventListener('dragover',e=>{if(e.target.closest('[data-studio-drop-phase],[data-studio-node]'))e.preventDefault()});document.addEventListener('drop',e=>{const p=e.target.closest('[data-studio-drop-phase]'),n=e.target.closest('[data-studio-node]');if(!p&&!n)return;e.preventDefault();const k=e.dataTransfer.getData('text/plain')||studioDragKey;if(n){const target=studioDraft.definition.steps.find(s=>s.key===n.dataset.studioNode);studioMove(k,studioPhase(target),target.key)}else studioMove(k,p.dataset.studioDropPhase);studioDragKey=null});

document.addEventListener('click',event=>{if(event.target.closest('button[data-studio-complete-template]'))run(()=>studioStart(studioCompleteJourney));},{capture:true});

document.addEventListener('change',event=>{if(event.target.hasAttribute?.('data-studio-run-filter')){studioRunFilter=['active','attention','all'].includes(event.target.value)?event.target.value:'active';studioRender();}});
